def slug(s): return re.sub(r'[^a-z0-9]+','-',s.lower()).strip('-')
def write(path, content):
    from doc_icons import decorate_markdown
    if path.suffix == '.md':
        content = decorate_markdown(content, lesson=path.name == 'lesson.md')
    path.parent.mkdir(parents=True,exist_ok=True); path.write_text(content+'\n',encoding='utf-8')

rows=[line.split('|') for line in DATA.splitlines()]
assert len(rows)==60 and all(len(r)==8 for r in rows)
catalog=[]
for pi,(folder,phase,project) in enumerate(PHASES):
    p=ROOT/folder; lessons=[]
    for li,row in enumerate(rows[pi*5:pi*5+5]):
        title,concept,scenario,exercise,evidence,q,a,link=row
        n=pi*5+li; day=1+n*21//60; lid=f'{pi+1:02}-{li+1:02}'
        dest=p/f'{li+1:02}-{slug(title)}'; rel=dest.relative_to(ROOT).as_posix()
        objectives=f'- Explain {title.lower()} in your own words.\n- Apply the concept to the customer scenario.\n- Produce and independently verify the requested evidence.'
        prior='No prior coding experience required.' if n==0 else f'Complete lesson {catalog[-1]["id"]}: {catalog[-1]["title"]}; use synthetic data.'
        quiz=f'1. {q}\n2. What evidence would show your exercise works?\n3. What should you do if the evidence fails?'
        answers=f'1. {a}\n2. {evidence}\n3. Record the failure, correct the smallest issue, and rerun the check.'
        lesson=f'# {title}\n\n## Why this matters\n{scenario}\n\n## Learning objectives\n{objectives}\n\n## Prerequisites\n{prior}\n\n## Concepts\n{concept}\n\n## Build it\n1. Read the scenario and identify the input and expected output.\n2. {exercise}\n3. Verify the result using the success evidence below.\n\n## Real-world scenario\n{scenario} An FDE documents assumptions, tests the smallest useful change and reviews the outcome with the workflow owner.\n\n## Common mistakes\n- Treating a generated result as verified evidence. Check it independently.\n- Using real customer data in a learning demo. Use synthetic records.\n- Hiding missing evidence. Document limitations and ask for review.\n\n## Checkpoint\n{quiz}\n\n## Deliverable\n{evidence}\n\n## Further reading\n- [Reference]({link})'
        write(dest/'lesson.md',lesson); write(dest/'README.md',f'# {title}\n\nDay {day} · 20 minutes · [Lesson](lesson.md) · [Exercise](exercise.md) · [Quiz](quiz.md)\n\n{concept}')
        write(dest/'exercise.md',f'# Practice: {title}\n\n{scenario}\n\n1. {exercise}\n2. Record inputs and outputs.\n3. Try a boundary case.\n\n## Acceptance\n{evidence}\n\n## Submission\nSave your work and a brief explanation of any limitations.')
        write(dest/'quiz.md',f'# Check your understanding\n\n{quiz}\n\n<details><summary>Answers</summary>\n\n{answers}\n\n</details>')
        item=dict(id=lid,title=title,phase=pi+1,phaseTitle=phase,day=day,minutes=20,difficulty='Beginner' if pi<4 else 'Intermediate',project=project,prerequisites=prior,deliverable=evidence,path=f'curriculum/{rel}/lesson.md',lesson=lesson,exercise=exercise,quiz=quiz,answers=answers)
        lessons.append(item); catalog.append(item)
    write(p/'README.md',f'# Phase {pi+1}: {phase}\n\nFive lessons · 100 minutes · Project: {project}\n\n## Lessons\n'+ '\n'.join(f'- [{x["title"]}]({Path(x["path"]).parent.name}/lesson.md)' for x in lessons)+f'\n\n## Mini-project\nCombine the five lesson deliverables into a {project} evidence bundle.\n\n## Real FDE scenario\n{rows[pi*5][2]}\n\n## Success criteria\n'+ '\n'.join(f'- {x["deliverable"]}' for x in lessons)+f'\n\n## Phase quiz\n'+'\n'.join(f'- {rows[pi*5+i][5]}' for i in range(5)))
    write(p/'project.md',f'# Mini-project: {project}\n\nUse the five lesson deliverables in this phase. Combine them into a single README with a customer brief, steps, evidence, limitations, and next decision.\n\n## Acceptance\n'+'\n'.join(f'- {x["deliverable"]}' for x in lessons))
write(ROOT/'README.md','# Zero to FDE curriculum\n\n21-day guided core · 60 lessons · 20 hours of lesson time. Allow additional time for complete portfolio projects. Start at phase 1 and follow the order below.\n\n'+'\n'.join(f'{i+1}. [{name}]({folder}/README.md)' for i,(folder,name,_) in enumerate(PHASES))+'\n\n[Career preparation](10-career-preparation/README.md)')
write(ROOT/'10-career-preparation/README.md','# Career preparation\n\nPractice explaining a customer workflow, trade-offs, evaluation, incident response and release decisions. Prepare a portfolio walkthrough supported by real artifacts.\n\n## Mock interview\n1. A customer asks for an AI chatbot. How do you discover the actual need?\n2. How would you evaluate a retrieval assistant?\n3. How do you handle a failing integration?\n4. What evidence supports a pilot rollout?\n5. How do you explain an AI limitation to a nontechnical stakeholder?\n\nAnswer each using situation, action, evidence, and trade-off. Avoid claiming simulated outcomes as production experience.')
write(ROOT/'assets/README.md','# Curriculum assets\n\nPlace original diagrams and synthetic sample datasets here. Do not commit customer data, credentials or proprietary material.')
write(ROOT.parent/'website/src/catalog.json',json.dumps(catalog,ensure_ascii=False,indent=2))
write(ROOT/'ROADMAP.md','# 21-day roadmap\n\n| Day | Lessons | Minutes |\n|---|---|---:|\n'+'\n'.join(f'| {day} | '+ '; '.join(x['title'] for x in catalog if x['day']==day)+f' | {sum(x["minutes"] for x in catalog if x["day"]==day)} |' for day in range(1,22)))
